uniform float amzp_blend;



        float3 saturateCol(float3 col, float sat) {
            float grey = dot(col, float3(0.2126, 0.7152, 0.0722));
            return mix(float3(grey), col, sat);
        }

        float3 applyContrast(float3 col, float con) {
            return (col - 0.5) * con + 0.5;
        }


        float hash(float2 p) {
            return fract(sin(dot(p, float2(12.9898, 78.233))) * 43758.5453);
        }

        float noise(float2 p) {
            float2 i = floor(p); float2 f = fract(p);
            f = f * f * (3.0 - 2.0 * f);
            return mix(mix(hash(i), hash(i + float2(1,0)), f.x),
                       mix(hash(i + float2(0,1)), hash(i + float2(1,1)), f.x), f.y);
        }

        float getGrain(float2 uv, float t) {
            return hash(uv + t);
        }

        float getScratches(float2 uv, float t) {
            float x = uv.x * 200.0;
            float r = hash(float2(floor(x), floor(t * 10.0)));
            if (r > 0.99) return smoothstep(0.1, 0.0, abs(fract(x) - 0.5));
            return 0.0;
        }

        float getDust(float2 uv, float t) {
            float2 p = uv * 50.0;
            float n = noise(p + t * 5.0);
            return step(0.98, n) * hash(uv + t);
        }

        float3 getLightLeaks(float2 uv, float t) {
            float2 p = uv + float2(t * 0.1, sin(t * 0.5) * 0.2);
            float n = noise(p * 2.0);
            float3 c1 = float4(1.0, 0.4, 0.2, 1.0).rgb * smoothstep(0.4, 0.8, n);
            float3 c2 = float4(0.2, 0.4, 1.0, 1.0).rgb * smoothstep(0.4, 0.8, noise(p * 3.0 + 10.0));
            return (c1 + c2) * 0.5;
        }

        float3 applyBloom(float3 col, float str) {
            float luma = dot(col, float3(0.2126, 0.7152, 0.0722));
            float3 highlight = col * smoothstep(0.6, 1.0, luma);
            return col + highlight * str * 2.0;
        }

        float3 applyVignette(float3 col, float2 uv, float str) {
            float d = distance(uv, float2(0.5));
            return col * smoothstep(0.8, 0.4 + (1.0 - str) * 0.4, d);
        }

        float3 getGlitch(float2 uv, float t, float str) {
            float2 gUv = uv;
            float gNoise = hash(float2(floor(t * 10.0), floor(uv.y * 10.0)));
            if (gNoise > 0.98) gUv.x += (hash(float2(t)) - 0.5) * 0.05 * str;
            return amzTexture(0, gUv).rgb;
        }

        float getLensDirt(float2 uv, float t) {
            float dirt = noise(uv * 10.0 + t * 0.05);
            return smoothstep(0.7, 1.0, dirt) * 0.1;
        }

        float3 applyLetterbox(float3 col, float2 uv, float str) {
            float mask = step(0.1 * str, uv.y) * step(uv.y, 1.0 - 0.1 * str);
            return col * mask;
        }

        float getStatic(float2 uv, float t) {
            return hash(uv + t * 20.0);
        }

        void amzRender() {
            float2 uv = amzScreenNorm();
            float t = time;


            float ca = amzp_vhsMode * 0.005;
            float4 srcR = amzTexture(0, uv + float2(ca, 0));
            float4 srcG = amzTexture(0, uv);
            float4 srcB = amzTexture(0, uv - float2(ca, 0));
            float3 col = float3(srcR.r, srcG.g, srcB.b);
            float alpha = srcG.a;


            if (amzp_vhsMode > 0.1) {
                float jitter = (hash(float2(t, uv.y)) - 0.5) * 0.01 * amzp_vhsMode;
                if (hash(float2(t * 0.5)) > 0.98) uv.x += jitter;
                col = amzTexture(0, uv).rgb;
            }


            float3 filterCol = col;

            if (int(amzp_filterMode) == 0) { 
                float luma = dot(col, float3(0.2126, 0.7152, 0.0722));
                filterCol.r = pow(col.r, 0.8) * 1.25;
                filterCol.g = col.g;
                filterCol.b = pow(col.b, 1.2) * 0.85;
                filterCol = mix(filterCol, float3(luma * 1.5, luma * 1.0, luma * 0.8), 0.15); 
            } 
            else if (int(amzp_filterMode) == 1) { 
                filterCol = col * float3(0.8, 0.9, 1.1);
                filterCol = applyContrast(filterCol, 1.2);
                filterCol = mix(filterCol, float3(dot(filterCol, float3(0.3, 0.59, 0.11))), 0.2); 
            }
            else if (int(amzp_filterMode) == 2) { 
                filterCol = col * float3(1.15, 0.95, 0.8);
                filterCol.r = smoothstep(0.0, 1.0, filterCol.r * 1.1);
                filterCol.b = pow(filterCol.b, 1.3);
            }
            else if (int(amzp_filterMode) == 3) { 
                float luma = dot(col, float3(0.2126, 0.7152, 0.0722));
                float3 overlay = (luma < 0.5) ? (2.0 * col * luma) : (1.0 - 2.0 * (1.0 - col) * (1.0 - luma));
                filterCol = mix(col, overlay, 0.6);
                filterCol = saturateCol(filterCol, 0.4);
            }
            else if (int(amzp_filterMode) == 4) { 
                filterCol = col * float3(1.1, 0.8, 1.2); 
                filterCol.r = pow(filterCol.r, 0.9);
                filterCol.b = pow(filterCol.b, 0.85);
                filterCol = applyContrast(filterCol, 1.1);
            }
            else if (int(amzp_filterMode) == 5) { 
                filterCol = col * float3(1.1, 1.05, 0.85);
                filterCol = mix(filterCol, float3(0.2, 0.15, 0.1), 0.1); 
                filterCol = saturateCol(filterCol, 0.8);
            }
            else if (int(amzp_filterMode) == 6) { 
                filterCol = col * float3(0.9, 1.1, 1.25);
                filterCol += 0.05; 
                filterCol = applyContrast(filterCol, 0.95);
            }
            else if (int(amzp_filterMode) == 7) { 
                filterCol = pow(col, float3(0.8)); 
                filterCol = saturateCol(filterCol, 1.1);
                filterCol = mix(filterCol, float3(1.0), 0.1); 
            }
            else if (int(amzp_filterMode) == 8) { 
                float luma = dot(col, float3(0.2126, 0.7152, 0.0722));
                filterCol = float3(pow(luma, 1.4) * 1.2);
                filterCol = applyContrast(filterCol, 1.3);
            }
            else if (int(amzp_filterMode) == 9) { 
                float luma = dot(col, float3(0.299, 0.587, 0.114));
                filterCol = float3(smoothstep(0.1, 0.9, luma));
                filterCol *= 0.9; 
            }
            else if (int(amzp_filterMode) == 10) { 
                filterCol = col * float3(1.3, 0.9, 0.7);
                filterCol.g = pow(filterCol.g, 1.1);
                filterCol.b = pow(filterCol.b, 1.4);
            }
            else if (int(amzp_filterMode) == 11) { 
                filterCol = col * float3(0.9, 1.15, 0.95);
                filterCol.rb = pow(filterCol.rb, float2(1.2));
                filterCol = mix(filterCol, float3(0.0, 0.1, 0.05), 0.1);
            }
            else if (int(amzp_filterMode) == 12) { 
                filterCol = col * float3(1.0, 1.0, 0.9);
                filterCol = applyContrast(filterCol, 1.15);
                filterCol = mix(filterCol, float3(0.1, 0.1, 0.2), 0.1); 
                filterCol = saturateCol(filterCol, 0.9);
            }
            else if (int(amzp_filterMode) == 13) { 
                float luma = dot(col, float3(0.21, 0.72, 0.07));
                filterCol = float3(luma * 1.2, luma * 0.5, luma * 0.9);
                filterCol.r = smoothstep(0.1, 0.9, filterCol.r);
            }
            else if (int(amzp_filterMode) == 14) { 
                filterCol = col * float3(1.1, 1.0, 0.8);
                filterCol = saturateCol(filterCol, 1.25);
                filterCol = applyContrast(filterCol, 1.1);
            }
            else if (int(amzp_filterMode) == 15) { 
                float luma = dot(col, float3(0.21, 0.72, 0.07));
                filterCol = float3(luma * 0.2, luma * 1.5, luma * 0.2);
            }
            else if (int(amzp_filterMode) == 16) { 
                float luma = dot(col, float3(0.21, 0.72, 0.07));
                filterCol = float3(luma) * float3(1.2, 1.0, 0.8);
                filterCol = applyContrast(filterCol, 1.1);
            }
            else if (int(amzp_filterMode) == 17) { 
                filterCol = pow(col, float3(0.8));
                filterCol = saturateCol(filterCol, 1.5);
                filterCol = applyContrast(filterCol, 1.2);
            }
            else if (int(amzp_filterMode) == 18) { 
                filterCol = col * float3(1.15, 1.05, 0.9);
                filterCol = mix(filterCol, float3(1.0, 0.8, 0.5), 0.05);
            }
            else if (int(amzp_filterMode) == 19) { 
                filterCol = applyContrast(col, 1.3);
                filterCol.r = pow(filterCol.r, 0.9);
                float luma = dot(col, float3(0.299, 0.587, 0.114));
                filterCol = float3(smoothstep(0.1, 0.9, luma));
                filterCol *= 0.9;
            }
            else if (int(amzp_filterMode) == 20) { 
                filterCol = col * float3(1.1, 0.95, 0.8);
                filterCol = applyContrast(filterCol, 1.2);
                filterCol += getLightLeaks(uv, t) * 0.3;
            }
            else if (int(amzp_filterMode) == 21) { 
                float luma = dot(col, float3(0.2126, 0.7152, 0.0722));
                filterCol = mix(col, float3(luma), 0.7);
                filterCol = applyContrast(filterCol, 1.5);
            }
            else if (int(amzp_filterMode) == 22) { 
                filterCol = col * float3(0.7, 0.85, 1.2);
                filterCol.r = pow(filterCol.r, 1.3);
            }
            else if (int(amzp_filterMode) == 23) { 
                filterCol = col * float3(1.2, 1.1, 0.9);
                filterCol = mix(filterCol, float3(1.0, 0.9, 0.7), 0.1);
            }
            else if (int(amzp_filterMode) == 24) { 
                filterCol = col * float3(1.4, 0.5, 1.2);
                filterCol = applyContrast(filterCol, 1.2);
            }
            else if (int(amzp_filterMode) == 25) { 
                filterCol = col * float3(0.5, 1.4, 0.5);
                filterCol = applyContrast(filterCol, 1.3);
            }
            else if (int(amzp_filterMode) == 26) { 
                filterCol = col * 0.8 + 0.2;
                filterCol = saturateCol(filterCol, 0.6);
            }
            else if (int(amzp_filterMode) == 27) { 
                filterCol = pow(col, float3(0.7)) * 1.1;
                filterCol = saturateCol(filterCol, 0.8);
            }
            else if (int(amzp_filterMode) == 28) { 
                filterCol = pow(col, float3(1.8));
                filterCol = applyContrast(filterCol, 1.1);
            }
            else if (int(amzp_filterMode) == 29) { 
                filterCol = applyBloom(col, 0.5);
                filterCol = saturateCol(filterCol, 1.1);
            }


            float grain = getGrain(uv, t) * 0.15;
            float scratches = getScratches(uv, t) * 0.5;
            float dust = getDust(uv, t) * 0.8;
            float scanline = sin(uv.y * 800.0) * 0.04;
            float3 leaks = getLightLeaks(uv, t) * 0.6;


            if (amzp_overlayStrength > 0.01) {

                bool isVintage = (int(amzp_filterMode) == 5 || int(amzp_filterMode) == 12 || int(amzp_filterMode) == 14 || int(amzp_filterMode) == 16 || int(amzp_filterMode) == 17 || int(amzp_filterMode) == 19 || int(amzp_filterMode) == 20 || int(amzp_filterMode) == 23 || int(amzp_filterMode) == 26);
                bool isDigital = (int(amzp_filterMode) == 4 || int(amzp_filterMode) == 13 || int(amzp_filterMode) == 15 || int(amzp_filterMode) == 24 || int(amzp_filterMode) == 25);
                bool isBright = (int(amzp_filterMode) == 2 || int(amzp_filterMode) == 6 || int(amzp_filterMode) == 7 || int(amzp_filterMode) == 10 || int(amzp_filterMode) == 27 || int(amzp_filterMode) == 29);
                bool isCinematic = (int(amzp_filterMode) == 0 || int(amzp_filterMode) == 1 || int(amzp_filterMode) == 3 || int(amzp_filterMode) == 8 || int(amzp_filterMode) == 9 || int(amzp_filterMode) == 11 || int(amzp_filterMode) == 18 || int(amzp_filterMode) == 21 || int(amzp_filterMode) == 22 || int(amzp_filterMode) == 28);

                if (isVintage) {
                    filterCol += (grain + scratches + dust) * amzp_overlayStrength;
                    filterCol += leaks * amzp_overlayStrength * 0.5;
                    filterCol *= 1.0 + (sin(t * 12.0) * 0.02 * amzp_overlayStrength); 
                }
                if (isDigital) {
                    filterCol -= scanline * amzp_overlayStrength;
                    filterCol += getStatic(uv, t) * 0.05 * amzp_overlayStrength;
                    if (hash(float2(t)) > 0.98) filterCol = getGlitch(uv, t, amzp_overlayStrength);
                }
                if (isBright) {
                    filterCol += getLensDirt(uv, t) * amzp_overlayStrength;
                    filterCol += leaks * 0.3 * amzp_overlayStrength;
                    filterCol = applyBloom(filterCol, 0.2 * amzp_overlayStrength);
                }
                if (isCinematic) {
                    filterCol = applyVignette(filterCol, uv, 0.6 * amzp_overlayStrength);
                    filterCol = applyLetterbox(filterCol, uv, 0.5 * amzp_overlayStrength);
                    filterCol += grain * 0.1 * amzp_overlayStrength;
                }
            }


            col = mix(col, filterCol, amzp_intensity);


            col += amzp_brightness;
            col = applyContrast(col, amzp_contrast);
            col = saturateCol(col, amzp_saturation);


            col = applyBloom(col, amzp_bloomStrength);
            col = applyVignette(col, uv, amzp_vignette);

            amzOutput = float4(col, alpha) * amzp_blend + (1.0 - amzp_blend) * srcG;
        }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }

